#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);
    if (s.length() >= 2) {
        s[1] = s[1]; // Keep the second character as is
    }
    if (s.length() > 2) {
        size_t start = 1;
        size_t end = s.length() - 1;
        std::string middle = s.substr(start, end - start);
        size_t pos = 0;
        while ((pos = middle.find("dot")) != std::string::npos) {
            middle.replace(pos, 3, ".");
        }
        s.replace(start, end - start, middle);
    }
    if (s.length() >= 2) {
        size_t start = 1;
        size_t end = s.length() - 1;
        std::string middle = s.substr(start, end - start);
        size_t pos = middle.find("at");
        if (pos != std::string::npos) {
            middle.replace(pos, 2, "@");
        }
        s.replace(start, end - start, middle);
    }
    std::cout << s << std::endl;
    return 0;
}
